def filter_above(nums, threshold, result=[]):
    for i in range(1, len(nums)):
        if nums[i] > threshold:
            result.append(nums[i])
    return result

n = int(input())
nums = list(map(int, input().split()))
k = int(input())
for _ in range(k):
    t = int(input())
    res = filter_above(nums, t)
    print(' '.join(map(str, res)))
